abi4.ll.text:
; Four far pointers: the fourth exceeds RL1..RL3.
define i8 @callee4(ptr addrspace(2) %a, ptr addrspace(2) %b, ptr addrspace(2) %c, ptr addrspace(2) %d) {
  %va = load volatile i8, ptr addrspace(2) %a
  %vd = load volatile i8, ptr addrspace(2) %d
  %s = add i8 %va, %vd
  ret i8 %s
}
define i8 @caller4(ptr addrspace(2) %a, ptr addrspace(2) %b, ptr addrspace(2) %c, ptr addrspace(2) %d) {
  %r = call i8 @callee4(ptr addrspace(2) %d, ptr addrspace(2) %c, ptr addrspace(2) %b, ptr addrspace(2) %a)
  ret i8 %r
}

abimix.ll.text:
; Seven near pointers occupy RS1..RS7 before a far pointer is assigned.
define i8 @calleemix(ptr %p1, ptr %p2, ptr %p3, ptr %p4, ptr %p5, ptr %p6, ptr %p7, ptr addrspace(2) %f) {
  %v = load volatile i8, ptr addrspace(2) %f
  %w = load volatile i8, ptr %p7
  %s = add i8 %v, %w
  ret i8 %s
}
define i8 @callermix(ptr addrspace(2) %f) {
  %r = call i8 @calleemix(ptr null, ptr null, ptr null, ptr null, ptr null, ptr null, ptr inttoptr (i16 7 to ptr), ptr addrspace(2) %f)
  ret i8 %r
}

